<?php require 'config/config.php';auth();$id=(int)($_GET['room_id']??$_POST['room_id']);$s=db()->prepare("SELECT r.*,p.title,p.city FROM rooms r JOIN properties p ON p.id=r.property_id WHERE r.id=? AND r.status='available'");$s->execute([$id]);$r=$s->fetch();if(!$r)exit('Room unavailable');if($_POST){check();$date=$_POST['move_in'];$months=(int)$_POST['months'];db()->prepare('INSERT INTO bookings(user_id,room_id,move_in_date,months,total_rent,advance_amount,status,payment_status) VALUES(?,?,?,?,?,?,?,?)')->execute([user()['id'],$id,$date,$months,$r['rent']*$months,$r['deposit'],'pending_payment','unpaid']);go(BASE_URL.'/pay.php?booking_id='.db()->lastInsertId());}$title='Book Room';require 'config/header.php';?><div class="auth"><div class="panel"><h1>Reserve <?=e($r['title'])?></h1><p>Advance to confirm: <b><?=money($r['deposit'])?></b></p><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="room_id" value="<?=$id?>"><label>Move-in date<input type="date" name="move_in" required></label><label>Rental period<select name="months"><?php for($i=1;$i<=12;$i++):?><option value="<?=$i?>"><?=$i?> month(s)</option><?php endfor;?></select></label><button class="btn">Continue to Payment</button></form></div></div><?php require 'config/footer.php';?>
